CREATE TABLE IF NOT EXISTS yonghu (id INT PRIMARY KEY AUTO_INCREMENT, zhanghao VARCHAR(50) UNIQUE, mima VARCHAR(255), mingcheng VARCHAR(50), juese VARCHAR(30)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS zuowu (id INT PRIMARY KEY AUTO_INCREMENT, mingcheng VARCHAR(50), shengyujie VARCHAR(50), xushui_xishu DOUBLE, xufei_xishu DOUBLE, shiyi_turang VARCHAR(100), mubiao_shidu DOUBLE, tuijian_shuifen TEXT, tuijian_feiliao TEXT, shuoming TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS zuowu_jieduan (id INT PRIMARY KEY AUTO_INCREMENT, zuowu_id INT, jieduan VARCHAR(50), xushui_xishu DOUBLE, xufei_xishu DOUBLE, mubiao_shidu_min DOUBLE, mubiao_shidu_max DOUBLE, nongyi_tishi TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS turang (id INT PRIMARY KEY AUTO_INCREMENT, zhidi VARCHAR(50), rongzhong DOUBLE, chitian_chishuiliang DOUBLE, ph DOUBLE, dian_daolv DOUBLE, qita TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shebei (id INT PRIMARY KEY AUTO_INCREMENT, mingcheng VARCHAR(100), leixing VARCHAR(50), zhuangtai VARCHAR(30), shuixiang DOUBLE, feixiang DOUBLE, liuliang DOUBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS feiliao (id INT PRIMARY KEY AUTO_INCREMENT, mingcheng VARCHAR(100), dan DOUBLE, lin DOUBLE, jia DOUBLE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS jiance (id INT PRIMARY KEY AUTO_INCREMENT, zuowu_id INT, shengyujie VARCHAR(50), turang_shidu DOUBLE, turang_wendu DOUBLE, kongqi_shidu DOUBLE, guangzhao DOUBLE, dian_daolv DOUBLE, jilu_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tianqi (id INT PRIMARY KEY AUTO_INCREMENT, yubaoriqi DATE UNIQUE, zuigao_wendu DOUBLE, zuidi_wendu DOUBLE, kongqi_shidu DOUBLE, jiangyu_gailv DOUBLE, jiangyu_liang DOUBLE, tianqi_leixing VARCHAR(30), zhengfa_liang DOUBLE, diqu VARCHAR(100), shuju_laiyuan VARCHAR(100), gengxin_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS yuce (id INT PRIMARY KEY AUTO_INCREMENT, zuowu_id INT, yuce_tianshu INT, xushui_json JSON, xufei_json JSON, shidu_json JSON, fenxi TEXT, tianqi_shuoming TEXT, jilu_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS juece (id INT PRIMARY KEY AUTO_INCREMENT, jiance_id INT, zuowu_id INT, zhuangtai VARCHAR(30), feili_zhuangtai VARCHAR(30), guangai_liang DOUBLE, shifei_liang DOUBLE, beng_yunxing DOUBLE, yuanyin TEXT, jilu_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS baogao (id INT PRIMARY KEY AUTO_INCREMENT, biaoti VARCHAR(200), chuangjian_shijian DATETIME, gengxin_shijian DATETIME, zuowu VARCHAR(50), zhaiyao TEXT, zhuangtai VARCHAR(30), daochuren VARCHAR(50), daochu_zhuangtai VARCHAR(30), neirong_json JSON) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS zhiling (id INT PRIMARY KEY AUTO_INCREMENT, shebei_id INT, guangai_liang DOUBLE, shifei_liang DOUBLE, beng_yunxing DOUBLE, zhuangtai VARCHAR(30), chuangjian_shijian DATETIME, xiafa_shijian DATETIME, caozuoren VARCHAR(50), caozuo_beizhu TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fankui (id INT PRIMARY KEY AUTO_INCREMENT, zhiling_id INT, shiji_guangai DOUBLE, shiji_shifei DOUBLE, zhuangtai VARCHAR(30), shangbao_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS yujing (id INT PRIMARY KEY AUTO_INCREMENT, leixing VARCHAR(50), mingcheng VARCHAR(50), zuixiao DOUBLE, zuida DOUBLE, dengji VARCHAR(20), shuoming TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rizhi (id INT PRIMARY KEY AUTO_INCREMENT, caozuo_shijian DATETIME, caozuo_leixing VARCHAR(50), caozuo_neirong TEXT, caozuoren VARCHAR(50)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS moxing_canshu (mingcheng VARCHAR(50) PRIMARY KEY, n INT, mean_x DOUBLE, mean_y DOUBLE, var_x DOUBLE, cov_xy DOUBLE, gengxin_shijian DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
